package com.bjjj.todo;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class WidgetTests extends Instrumentation {
 View findComplete(View v){if(v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith("完成 组件测试"))return v;if(v instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++){View found=findComplete(group.getChildAt(i));if(found!=null)return found;}return null;}
 View findCard(View v,String title){if(v.getContentDescription()!=null&&v.getContentDescription().toString().equals("完成 "+title))return (View)v.getParent();if(v instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=findCard(group.getChildAt(n),title);if(found!=null)return found;}return null;}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle status=new Bundle();status.putString("id","InstrumentationTestRunner");status.putInt("numtests",1);status.putInt("current",1);status.putString("class",getClass().getName());status.putString("test","persistenceAndNativeWidget");sendStatus(1,status);AppWidgetHost[] host={null};try{Context c=getTargetContext();c.deleteFile("tasks.json");JSONObject draft=new JSONObject().put("title","组件测试：论文图表核对").put("priority","high").put("category","research").put("due",java.time.Instant.now().plusSeconds(7200).toString()).put("offsets",new JSONArray());JSONObject task=Store.save(c,draft);check(Store.open(Store.read(c)).size()==1,"Task persisted");try{Store.save(c,new JSONObject().put("title"," "));throw new AssertionError("Empty title accepted");}catch(IllegalArgumentException ignored){}catch(Exception expected){}Store.done(c,task.getString("id"),true);Store.done(c,task.getString("id"),true);check(Store.open(Store.read(c)).isEmpty(),"Completion must be idempotent");Store.done(c,task.getString("id"),false);check(Reminder.offsetMillis(1d/60)==1000,"One second conversion");check(Reminder.offsetMillis(7d/60)==7000,"Seconds are rounded without truncation");check(Reminder.offsetMillis(30)==1800000,"Legacy minute conversion");for(String level:new String[]{"normal","low"})Store.save(c,new JSONObject().put("title","组件测试："+level).put("priority",level));
  MainActivity activity=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));int[] widgetId={0};AppWidgetHostView[] view={null};runOnMainSync(()->{host[0]=new AppWidgetHost(activity,201);widgetId[0]=host[0].allocateAppWidgetId();AppWidgetManager m=AppWidgetManager.getInstance(activity);Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,350);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,600);check(m.bindAppWidgetIdIfAllowed(widgetId[0],new ComponentName(activity,TodoWidget.class),options),"Widget binding permission");view[0]=host[0].createView(activity,widgetId[0],m.getAppWidgetInfo(widgetId[0]));activity.setContentView(view[0]);host[0].startListening();TodoWidget.updateAll(activity);});
  View[] checkbox={null};for(int attempt=0;attempt<80&&checkbox[0]==null;attempt++){Thread.sleep(250);runOnMainSync(()->checkbox[0]=findComplete(view[0]));}waitForIdleSync();Thread.sleep(1200);try(java.io.FileOutputStream output=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),"widget-test.png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,output);}check(checkbox[0]!=null,"Native scrolling collection rendered");runOnMainSync(()->{String[] names={"组件测试：论文图表核对","组件测试：normal","组件测试：low"};int[] colors={0xfff1d1d5,0xfff2e4bc,0xffcfdfef};for(int n=0;n<names.length;n++){View card=findCard(view[0],names[n]);check(card!=null,"Priority row is visible");check(((android.graphics.drawable.GradientDrawable)card.getBackground()).getColor().getDefaultColor()==colors[n],"Priority card background");}});runOnMainSync(()->checkbox[0].performClick());for(int i=0;i<40&&Store.open(Store.read(c)).size()!=2;i++)Thread.sleep(150);check(Store.open(Store.read(c)).size()==2,"Widget checkbox persisted completion");runOnMainSync(()->{host[0].deleteAppWidgetId(widgetId[0]);host[0].stopListening();activity.finish();});status.putString("stream","\nPassed persistence, validation, idempotent completion and native AppWidget list click.\n");sendStatus(0,status);Bundle result=new Bundle();result.putString("stream","\nOK (1 test)\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){status.putString("stack",android.util.Log.getStackTraceString(e));sendStatus(-2,status);Bundle result=new Bundle();result.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
